(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.25)*20 + Math.cos(y*0.012-t*0.18)*15;
  const w1y = Math.cos(y*0.015-t*0.22)*20 + Math.sin(x*0.013+t*0.3)*15;
  const w2x = Math.sin((x+w1x)*0.025+t*0.4)*10 + Math.cos((y+w1y)*0.02-t*0.35)*8;
  const w2y = Math.cos((y+w1y)*0.025-t*0.38)*10 + Math.sin((x+w1x)*0.022+t*0.42)*8;
  const w3x = Math.sin((x+w2x)*0.04+t*0.6)*5;
  const w3y = Math.cos((y+w2y)*0.04-t*0.55)*5;
  const sx = x + w1x + w2x + w3x, sy = y + w1y + w2y + w3y;
  const src = [
    [240+Math.sin(t*0.3)*120, 120+Math.cos(t*0.2)*80, 0.07, 2.0],
    [240+Math.cos(t*0.25)*100, 120+Math.sin(t*0.35)*60, 0.09, 1.7],
    [240+Math.sin(t*0.4+2)*80, 120+Math.cos(t*0.3+1)*100, 0.055, 2.4],
    [120+Math.cos(t*0.45+1)*60, 60+Math.sin(t*0.55+3)*40, 0.11, 1.5],
    [360+Math.sin(t*0.35+4)*70, 180+Math.cos(t*0.5+2)*50, 0.065, 2.7],
    [80+Math.cos(t*0.5+5)*90, 200+Math.sin(t*0.4)*60, 0.085, 1.9],
    [400+Math.sin(t*0.28+3)*50, 40+Math.cos(t*0.42+1)*70, 0.1, 2.1],
    [200+Math.cos(t*0.38+2)*110, 220+Math.sin(t*0.32+4)*50, 0.075, 2.3]
  ];
  let aS = 0, iS = 0;
  const waves = [];
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w = Math.sin(d*f - t*sp);
    waves.push(w);
    aS += w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  let cross = 0;
  for (let i = 0; i < waves.length; i += 2) cross += waves[i] * waves[(i+1) % waves.length];
  cross /= (waves.length / 2);
  const bg = (Math.sin(sx*0.03+sy*0.02+t*0.7) + Math.sin(sx*0.025-sy*0.035+t*0.9) + Math.sin(sx*0.05+sy*0.04-t*1.3)*0.5 + Math.sin((sx+sy)*0.08+t*2.0)*0.3) / 2.8;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral1 = (Math.sin(dist*0.04-ang*3-t*1.2) + Math.sin(dist*0.035+ang*4-t*0.9))*0.35;
  const spiral2 = (Math.sin(dist*0.06-ang*2+t*0.8) + Math.sin(dist*0.025+ang*5+t*1.1))*0.2;
  const c2x = 100+Math.sin(t*0.2)*60, c2y = 180+Math.cos(t*0.25)*40;
  const d2 = Math.sqrt((sx-c2x)**2 + (sy-c2y)**2), a2 = Math.atan2(sy-c2y, sx-c2x);
  const spiral3 = Math.sin(d2*0.05-a2*3+t*1.5)*0.25;
  const cell = Math.tanh((Math.sin(sx*0.12)*Math.sin(sy*0.12) + Math.sin((sx+sy)*0.08+t*0.7)*0.5 + Math.sin(sx*0.06-sy*0.09+t*0.5)*0.3)*1.5)*0.25;
  const micro = Math.sin(sx*0.3+t*2)*Math.sin(sy*0.25-t*1.8)*0.08;
  const raw = aS/8 - iS*0.6/8 + cross*0.4 + bg*0.25 + spiral1 + spiral2 + spiral3 + cell + micro;
  const reaction = Math.tanh(raw * 1.8);
  const breath = 0.92 + Math.sin(t*0.5)*0.08;
  const blend = reaction * breath, v = blend*0.5+0.5;
  const pal = [[5,12,52],[12,45,85],[18,95,115],[35,155,145],[120,195,130],[210,195,80],[225,140,65],[195,80,95],[120,40,85],[55,18,70],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
